bodies.css_snippet:
html {
  --theme-color: #121469;
}
body {
  font-family: 'Corpid', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  color: #565b5e;
  background-color: #ffffff;
}
.o-header {
  background-color: #121469;
}
.m-menu-main__link {
  color: #ffffff;
  font-weight: 600;
}
.m-search-bar__input {
  border: 1px solid #eff3f4;
  border-radius: 4px;
}
a {
  color: #236ba0;
  text-decoration: underline;
}
.m-logo__image {
  width: 254px;
  height: 72px;
}

.header-logo {
  background-color: #154273;
}
body {
  font-family: RijksSans, 'RO Sans', Calibri, Verdana, Arial, sans-serif;
  color: #000000;
  background-color: #ffffff;
}
h1, h2, h3 {
  font-family: 'RO Serif', 'Noto Serif', 'Times New Roman', serif;
}
a {
  color: #007bc7;
  text-decoration: underline;
}
.editorial-nav__title {
  color: #154273;
  font-weight: 700;
}
.hero-block__title {
  color: #ffffff;
}
.accent-highlight {
  background-color: #ffb612;
}

:root {
  --blue-500: #004682;
  --light-blue-500: #0073d6;
}
body {
  font-family: 'Politie Text', Arial, sans-serif;
  color: #202020;
  background-color: #ffffff;
}
.hero {
  background-color: var(--blue-500);
  color: #ffffff;
}
.group-hover\:text-light-blue-500:hover {
  color: var(--light-blue-500);
}
.group-visited\:text-purple-500:visited {
  color: #8b5cf6;
}
.accent {
  background-color: #fdc61e;
}
